command:
$ErrorActionPreference="Stop"
$root=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $root
& git fetch origin main work/search-v3-indexed-filename-20261008 --no-tags
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne "387efa622f6a9ce6685e3bffb98299df0503de3c"){throw "main changed"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){throw "canonical checkout dirty"}
$sourceRef="ffc2466be51c32c1cf7454a2df80fe4f8c3f5f99:tests/winui/test_indexed_search_gui.py"
$harness=Join-Path $root "logs\search-v3-indexed\visual-harness-before.py"
New-Item -ItemType Directory -Force -Path (Split-Path $harness) | Out-Null
$lines=@(& git show $sourceRef)
if($LASTEXITCODE -ne 0 -or $lines.Count -lt 30){throw "candidate harness unavailable"}
[IO.File]::WriteAllText($harness,($lines -join "`n"),(New-Object Text.UTF8Encoding($false)))
try {
 & git switch main
 if($LASTEXITCODE -ne 0){throw "main checkout failed"}
 & git merge --ff-only origin/main
 if($LASTEXITCODE -ne 0){throw "main restore failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "baseline Release build failed"}
 $env:PYTHONPATH=Join-Path $root "tests\winui"
 & python -X utf8 $harness --configuration Release --capture before
 if($LASTEXITCODE -ne 0){throw "controlled baseline GUI capture failed"}
 Write-Host "INDEXED_VISUAL_CONTROLLED_BEFORE=PASS"
} finally {
 Remove-Item -LiteralPath $harness -Force -ErrorAction SilentlyContinue
 & git switch main
 if($LASTEXITCODE -ne 0){throw "main not restored"}
}
